-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Fahre mit der Maus über den Charakter, die Namensplakette oder den Einheitenrahmen eines QT-Spielers, um „Dieser Spieler verwendet QuestTogether.“ zu sehen. Spieler, die nach Quest-Partnern suchen, zeigen ebenfalls diesen Status und ein leuchtendes QT-Logo an.","Der QT-Abschnitt passt sich Breite und Skalierung des Tooltips an, hält Abstand zu seiner Gesundheitsleiste und wird über den Tooltip verschoben, wenn darunter wenig Platz ist."},["title"]="QuestTogether-Spielertooltips"},{["illustration"]="quest-partners",["items"]={"Das goldene Namensplaketten-Leuchten reicht jetzt doppelt so weit um das Logo, während das Logo selbst gleich groß bleibt.","Symbole und Leuchteffekte zeigen echte QT-Nutzer und ihren aktuellen Status bei der Partnersuche an."},["title"]="Ein auffälligeres Partnerleuchten"}},["version"]="5.16.1",["welcome"]="Erkenne QuestTogether-Spieler anhand ihrer Tooltips und finde Quest-Partner leichter."},["esES"]={["sections"]={{["items"]={"Pasa el cursor sobre el personaje, la placa de nombre o el marco de unidad de un jugador de QT para ver «Este jugador usa QuestTogether». Los jugadores que buscan compañeros para hacer misiones también muestran ese estado y un logotipo de QT brillante.","La sección de QT se ajusta al ancho y la escala de la descripción emergente, se mantiene separada de su barra de salud y se desplaza encima de la descripción emergente cuando el espacio inferior es limitado."},["title"]="Descripciones emergentes de jugadores de QuestTogether"},{["illustration"]="quest-partners",["items"]={"El brillo dorado de la placa de nombre ahora llega el doble de lejos alrededor del logotipo, manteniendo el logotipo del mismo tamaño.","Los iconos y brillos reflejan usuarios reales de QT y su estado actual de búsqueda de compañeros."},["title"]="Un brillo de compañero más visible"}},["version"]="5.16.1",["welcome"]="Reconoce a los jugadores de QuestTogether por sus descripciones emergentes y encuentra compañeros de misiones más fácilmente."},["esMX"]={["sections"]={{["items"]={"Pasa el cursor sobre el personaje, la barra de nombre o el marco de unidad de un jugador de QT para ver “Este jugador está usando QuestTogether.” Los jugadores que buscan compañeros de misiones también muestran ese estado y un logo de QT brillante.","La sección de QT coincide con el ancho y la escala del tooltip, queda separada de su barra de salud y se mueve encima del tooltip cuando el espacio debajo es limitado."},["title"]="Tooltips de jugadores de QuestTogether"},{["illustration"]="quest-partners",["items"]={"El brillo dorado de la barra de nombre ahora se extiende el doble alrededor del logo, manteniendo el logo del mismo tamaño.","Los íconos y brillos reflejan a usuarios reales de QT y su estado actual de búsqueda de compañeros."},["title"]="Un brillo de compañero más visible"}},["version"]="5.16.1",["welcome"]="Reconoce a los jugadores de QuestTogether por sus tooltips y encuentra compañeros de misiones más fácilmente."},["frFR"]={["sections"]={{["items"]={"Survolez le personnage, la barre d’identification ou le cadre d’unité d’un joueur QT pour voir « Ce joueur utilise QuestTogether. » Les joueurs qui cherchent des partenaires de quête affichent également ce statut et un logo QT lumineux.","La section QT correspond à la largeur et à l’échelle de l’infobulle, reste à l’écart de sa barre de vie et se déplace au-dessus de l’infobulle quand l’espace en dessous est limité."},["title"]="Infobulles des joueurs QuestTogether"},{["illustration"]="quest-partners",["items"]={"La lueur dorée de la barre d’identification s’étend désormais deux fois plus loin autour du logo, tout en conservant la même taille pour le logo lui-même.","Les icônes et les lueurs reflètent les vrais utilisateurs de QT et leur statut actuel de recherche de partenaire."},["title"]="Une lueur de partenaire plus visible"}},["version"]="5.16.1",["welcome"]="Reconnaissez les joueurs de QuestTogether grâce à leurs infobulles et repérez plus facilement des partenaires de quête."},["itIT"]={["sections"]={{["items"]={"Passa il cursore sul personaggio, sulla barra del nome o sul riquadro unità di un giocatore QT per vedere “Questo giocatore usa QuestTogether.” I giocatori in cerca di compagni per le missioni mostrano anche quello stato e un logo QT luminoso.","La sezione QT si adatta alla larghezza e alla scala del tooltip, resta separata dalla sua barra della salute e si sposta sopra il tooltip quando lo spazio sotto è limitato."},["title"]="Tooltip dei giocatori di QuestTogether"},{["illustration"]="quest-partners",["items"]={"Il bagliore dorato della barra del nome ora si estende il doppio intorno al logo, mantenendo il logo stesso della stessa dimensione.","Le icone e i bagliori rispecchiano i veri utenti QT e il loro attuale stato di ricerca compagni."},["title"]="Un bagliore dei compagni più visibile"}},["version"]="5.16.1",["welcome"]="Riconosci i giocatori di QuestTogether dai loro tooltip e individua più facilmente compagni per le missioni."},["koKR"]={["sections"]={{["items"]={"QT 플레이어의 캐릭터, 이름표 또는 유닛 프레임에 마우스를 올리면 “이 플레이어는 QuestTogether를 사용 중입니다.”가 표시됩니다. 퀘스트 동료를 찾는 플레이어는 해당 상태와 빛나는 QT 로고도 표시됩니다.","QT 섹션은 툴팁의 너비와 크기에 맞춰지고, 생명력 바와 겹치지 않게 배치되며, 아래 공간이 부족하면 툴팁 위로 이동합니다."},["title"]="QuestTogether 플레이어 툴팁"},{["illustration"]="quest-partners",["items"]={"금색 이름표 발광 효과가 이제 로고 자체 크기는 그대로 유지하면서 로고 주위로 두 배 더 멀리 퍼집니다.","아이콘과 발광 효과는 실제 QT 사용자와 현재 동료 찾기 상태를 반영합니다."},["title"]="더 잘 보이는 동료 발광 효과"}},["version"]="5.16.1",["welcome"]="툴팁으로 QuestTogether 플레이어를 알아보고 퀘스트 동료를 더 쉽게 찾으세요."},["ptBR"]={["sections"]={{["items"]={"Passe o mouse sobre o personagem, a barra de nome ou o quadro de unidade de um jogador QT para ver “Este jogador está usando QuestTogether.” Jogadores procurando parceiros para fazer missões também mostram esse status e um logotipo QT brilhante.","A seção QT acompanha a largura e a escala do tooltip, fica afastada da barra de vida e se move para cima do tooltip quando o espaço abaixo é limitado."},["title"]="Tooltips de jogadores do QuestTogether"},{["illustration"]="quest-partners",["items"]={"O brilho dourado da barra de nome agora se estende duas vezes mais ao redor do logotipo, mantendo o logotipo em si do mesmo tamanho.","Ícones e brilhos refletem usuários reais do QT e o status atual deles de procura por parceiros."},["title"]="Um brilho de parceiro mais visível"}},["version"]="5.16.1",["welcome"]="Reconheça jogadores do QuestTogether pelos tooltips deles e encontre parceiros de missões com mais facilidade."},["ruRU"]={["sections"]={{["items"]={"Наведите курсор на персонажа, индикатор имени или рамку юнита игрока QT, чтобы увидеть «Этот игрок использует QuestTogether». У игроков, ищущих напарников для заданий, также отображается этот статус и светящийся логотип QT.","Раздел QT соответствует ширине и масштабу подсказки, не перекрывает ее полосу здоровья и перемещается над подсказкой, когда снизу мало места."},["title"]="Подсказки игроков QuestTogether"},{["illustration"]="quest-partners",["items"]={"Золотое свечение индикатора имени теперь распространяется вокруг логотипа вдвое дальше, при этом сам логотип остается того же размера.","Значки и свечение отражают реальных пользователей QT и их текущий статус поиска напарников."},["title"]="Более заметное свечение напарника"}},["version"]="5.16.1",["welcome"]="Распознавайте игроков QuestTogether по их подсказкам и легче находите напарников для заданий."},["zhCN"]={["sections"]={{["items"]={"将鼠标悬停在 QT 玩家的角色、姓名板或单位框体上，可看到“该玩家正在使用 QuestTogether。”正在寻找任务伙伴的玩家也会显示该状态和发光的 QT 标志。","QT 部分会匹配鼠标提示的宽度和缩放，避开其生命条，并在下方空间有限时移动到鼠标提示上方。"},["title"]="QuestTogether 玩家鼠标提示"},{["illustration"]="quest-partners",["items"]={"金色姓名板发光效果现在会在标志周围延伸两倍远，同时保持标志本身大小不变。","图标和发光效果会反映真实的 QT 用户及其当前寻找伙伴的状态。"},["title"]="更醒目的伙伴发光效果"}},["version"]="5.16.1",["welcome"]="通过鼠标提示识别 QuestTogether 玩家，并更轻松地发现任务伙伴。"},["zhTW"]={["sections"]={{["items"]={"將滑鼠移到 QT 玩家的角色、名條或單位框架上，即可看到「此玩家正在使用 QuestTogether。」正在尋找任務夥伴的玩家也會顯示該狀態與發光的 QT 標誌。","QT 區塊會符合提示資訊的寬度與縮放比例，避開其生命條，並在下方空間不足時移到提示資訊上方。"},["title"]="QuestTogether 玩家提示資訊"},{["illustration"]="quest-partners",["items"]={"金色名條發光效果現在會在標誌周圍延伸兩倍遠，同時保持標誌本身大小不變。","圖示與發光效果會反映真正的 QT 使用者及其目前尋找夥伴的狀態。"},["title"]="更顯眼的夥伴發光效果"}},["version"]="5.16.1",["welcome"]="透過提示資訊辨識 QuestTogether 玩家，並更容易找到任務夥伴。"}}
